package hu.synostream.android;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.io.*;
public class TorrentRulesTest {
    static final class Memory implements DownloadStation.Persistence {final Map<String,String> values=new HashMap<>();public String get(String k,String fallback){return values.getOrDefault(k,fallback);}public void put(String k,String v){values.put(k,v);}}
    static final class Fake implements DownloadStation.Transport {final Memory memory;final List<String> calls=new ArrayList<>();JSONObject selected;boolean uncertain=false,unsupported=false,rejected=false;Fake(Memory m){memory=m;}
        public JSONObject call(String api,String method,boolean read,JSONObject params,String name,byte[] bytes)throws Exception{calls.add(api+":"+method);if(unsupported)throw new IOException("Unsupported API");if(method.equals("create")){assertEquals(DownloadStation.TASK2,api);assertTrue(params.getBoolean("create_list"));return new JSONObject().put("list_id",new JSONArray().put("preview-1"));}if(api.equals(DownloadStation.LIST)&&method.equals("get"))return new JSONObject().put("title","Movie").put("files",new JSONArray().put(new JSONObject().put("index",0).put("name","Movie.mkv")).put(new JSONObject().put("index",1).put("name","release.nfo")).put(new JSONObject().put("index",2).put("name","Sample/clip.mkv")));if(method.equals("download")){assertTrue("Submission must be persisted before contacting NAS",memory.get("prepared:user","").contains("\"submitted\":true"));if(uncertain)throw new IOException("Unknown result");selected=params;return new JSONObject().put("task_id","ticket-1");}if(method.equals("download_status"))return new JSONObject().put("finish",true).put("success",!rejected);return new JSONObject();}}
    @Test public void nfoIsSelectedButEverySamplePathIsExcluded(){assertTrue(DownloadStation.defaultSelected("release.nfo"));assertTrue(DownloadStation.defaultSelected("movie.mkv"));assertFalse(DownloadStation.defaultSelected("SAMPLE/movie.mkv"));assertFalse(DownloadStation.defaultSelected("movie.sample.720p.mkv"));}
    @Test public void prepareNeverStartsAndStartSendsExactlyChosenIndices()throws Exception{Memory m=new Memory();Fake f=new Fake(m);DownloadStation ds=new DownloadStation(f,m,"user");List<JSONObject> previews=ds.prepare("magnet:?xt=urn:btih:abcdef",null,null,"/video/Filmek");assertEquals(1,previews.size());assertFalse(f.calls.stream().anyMatch(c->c.endsWith(":download")));ds.start("preview-1",Set.of(0,1));assertEquals(List.of(0,1),List.of(f.selected.getJSONArray("selected").getInt(0),f.selected.getJSONArray("selected").getInt(1)));assertEquals("video/Filmek",f.selected.getString("destination"));assertTrue(ds.prepared.isEmpty());}
    @Test public void emptySelectionCannotStart()throws Exception{Memory m=new Memory();Fake f=new Fake(m);DownloadStation ds=new DownloadStation(f,m,"user");ds.prepare("https://example.org/movie.torrent",null,null,"video");try{ds.start("preview-1",Set.of());fail();}catch(IllegalArgumentException expected){}assertFalse(ds.prepared.get("preview-1").getBoolean("submitted"));assertFalse(f.calls.stream().anyMatch(c->c.endsWith(":download")));}
    @Test public void uncertainStartIsNotReplayedAfterReload()throws Exception{Memory m=new Memory();Fake f=new Fake(m);DownloadStation ds=new DownloadStation(f,m,"user");ds.prepare("https://example.org/movie.torrent",null,null,"video");f.uncertain=true;try{ds.start("preview-1",Set.of(0));fail();}catch(IOException expected){}DownloadStation restarted=new DownloadStation(f,m,"user");try{restarted.start("preview-1",Set.of(0));fail();}catch(IOException expected){}assertEquals(1,f.calls.stream().filter(c->c.endsWith(":download")).count());}
    @Test public void unsupportedSelectionDoesNotFallBackToLegacyAutoStart()throws Exception{Memory m=new Memory();Fake f=new Fake(m);f.unsupported=true;DownloadStation ds=new DownloadStation(f,m,"user");try{ds.prepare("https://example.org/movie.torrent",null,null,"video");fail();}catch(IOException expected){}assertEquals(List.of(DownloadStation.TASK2+":create"),f.calls);}
    @Test public void duplicateAndFractionalIndicesAreRejected()throws Exception{for(String files:List.of("[{\"index\":1,\"name\":\"a\"},{\"index\":1,\"name\":\"b\"}]","[{\"index\":1.5,\"name\":\"a\"}]")){try{DownloadStation.files(new JSONObject().put("files",new JSONArray(files)));fail();}catch(IOException expected){}}}
    @Test public void magnetAndDestinationValidation(){assertEquals("magnet:?xt=urn:btih:abc",DownloadStation.uri("magnet:?xt=urn:btih:abc"));assertEquals("video/Filmek",DownloadStation.destination("/video/Filmek/"));for(String path:List.of("/video/../secret","/video/./film")){try{DownloadStation.destination(path);fail();}catch(IllegalArgumentException expected){}}for(String url:List.of("magnet:?dn=bad","file:///tmp/movie","https://example.org/a\nhttps://example.org/b")){try{DownloadStation.uri(url);fail();}catch(IllegalArgumentException expected){}}}
    @Test public void cancelledPreviewNeverDownloads()throws Exception{Memory m=new Memory();Fake f=new Fake(m);DownloadStation ds=new DownloadStation(f,m,"user");ds.prepare("https://example.org/movie.torrent",null,null,"video");ds.discard("preview-1");assertTrue(ds.prepared.isEmpty());assertTrue(f.calls.contains(DownloadStation.LIST+":delete"));assertFalse(f.calls.stream().anyMatch(c->c.endsWith(":download")));}
 @Test public void definiteFailedStartCanBeDiscarded()throws Exception{Memory m=new Memory();Fake f=new Fake(m);DownloadStation ds=new DownloadStation(f,m,"user");ds.prepare("https://example.org/a.torrent",null,null,"video");f.rejected=true;try{ds.start("preview-1",Set.of(0));fail();}catch(IOException expected){}assertFalse(ds.prepared.get("preview-1").getBoolean("submitted"));ds.discard("preview-1");assertTrue(ds.prepared.isEmpty());assertTrue(f.calls.contains(DownloadStation.LIST+":delete"));}
 @Test public void explicitNasRejectionIsRetryableButNetworkFailureStaysGuarded()throws Exception{Memory m=new Memory();Fake base=new Fake(m);DownloadStation.Transport rejected=(api,method,read,params,name,bytes)->{if(method.equals("download"))throw new NasClient.ApiRejectedException("Elutasítva");return base.call(api,method,read,params,name,bytes);};DownloadStation ds=new DownloadStation(rejected,m,"user");ds.prepare("https://example.org/a.torrent",null,null,"video");try{ds.start("preview-1",Set.of(0));fail();}catch(NasClient.ApiRejectedException expected){}assertFalse(new DownloadStation(rejected,m,"user").prepared.get("preview-1").getBoolean("submitted"));ds.discard("preview-1");assertTrue(ds.prepared.isEmpty());}
}
